int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *m,
                 size_t buf_len, int flags)
{
    struct sock *sk = sock->sk;
    int error, len = 0;
    long timeo;

    if (m == NULL || sk == NULL)
        return -EINVAL;

    lock_sock(sk);

    timeo = sock_rcvtimeo(sk, flags & MSG_DONTWAIT);

    while (1) {
        int copied = 0;

        if (sk->sk_state == TCP_LISTEN) {
            error = -ENOTCONN;
            goto out;
        }

        if (sk->sk_err || (sk->sk_shutdown & RCV_SHUTDOWN)) {
            if (copied || !timeo || (sk->sk_shutdown & RCV_SHUTDOWN))
                goto out;
        }

        error = sk->sk_prot->recvmsg(iocb, sk, m, buf_len, flags, &copied);
        if (error < 0) {
            len = error;
            goto out;
        }

        len += error;
        copied = 0;

        if (len < 0)
            goto out;

        if (!m->msg_flags || (m->msg_flags & MSG_MORE))
            break;

        if (signal_pending(current)) {
            if (!len)
                len = -ERESTARTSYS;
            break;
        }

        if (!timeo) {
            if (!len)
                len = -EAGAIN;
            break;
        }

        timeo = schedule_timeout(timeo);
    }

out:
    release_sock(sk);
    return len;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *m,
                 size_t buf_len, int flags)
{
    int ret;
    struct sk_buff *skb;
    size_t len;

    if (!sock || !m || buf_len == 0)
        return -EINVAL;

    lock_sock(sock);

    while (1) {
        if (sock->sk->sk_shutdown & RCV_SHUTDOWN)
            break;

        skb = skb_peek(&sock->sk->sk_receive_queue);
        if (!skb) {
            if (flags & MSG_DONTWAIT) {
                ret = -EAGAIN;
                goto out;
            }
            wait_for_rx_data(sock);
            continue;
        }

        len = min(skb->len, buf_len);
        if (len == 0) {
            ret = 0;
            goto out;
        }

        ret = skb_copy_datagram_iovec(skb, 0, m->msg_iov, len);
        if (ret)
            goto out;

        m->msg_iter.consumed += len;
        sock->sk->sk_data_processed += len;

        if (skb->len == len) {
            __skb_unlink(skb, &sock->sk->sk_receive_queue);
            kfree_skb(skb);
        }

        ret = len;
        break;
    }

    if (ret == 0)
        ret = -ENODATA;
    else if (ret < 0)
        ret = -EFAULT;

out:
    release_sock(sock);
    return ret;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *m,
                 size_t buf_len, int flags)
{
    int ret;
    struct sock *sk = sock->sk;
    struct sk_buff *skb;

    if (!sock || !m || !buf_len)
        return -EINVAL;

    lock_sock(sk);

    if (sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    while (sk->sk_receive_queue.head == sk->sk_receive_queue.tail) {
        if (flags & MSG_DONTWAIT) {
            ret = -EAGAIN;
            goto out;
        }

        if (signal_pending(current)) {
            ret = -ERESTARTSYS;
            goto out;
        }

        sk_wait_event(sk, &sk->sk_receive_queue, 0);
    }

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        ret = -EIO;
        goto out;
    }

    m->msg_name = (void *)&skb->pkthdr;
    m->msg_namelen = sizeof(skb->pkthdr);

    ret = skb_copy_datagram_iovec(skb, 0, m->msg_iov, buf_len);

    if (ret < 0) {
        kfree_skb(skb);
        goto out;
    }

    if (skb->len > buf_len) {
        m->msg_flags |= MSG_TRUNC;
    }

    if (skb->ip_summed != CHECKSUM_NONE) {
        m->msg_flags |= MSG_CTRUNC;
    }

    if (skb->pkt_type == PACKET_ERR) {
        m->msg_flags |= MSG_ERRQUEUE;
    }

    kfree_skb(skb);
    ret = buf_len;

out:
    release_sock(sk);
    return ret;
}

int recv_from_socket(struct kiocb *iocb, struct socket *sock, struct msghdr *m, size_t buf_len, int flags) {
    struct sock *sk = sock->sk;
    int res = 0;

    if (!sk || !m) {
        return -EINVAL;
    }

    lock_sock(sk);

    if (sk->sk_state == TCP_LISTEN) {
        release_sock(sk);
        return -EOPNOTSUPP;
    }

    while (1) {
        struct sk_buff *skb;
        int copied = 0;

        if (sk->sk_err) {
            res = -sk->sk_err;
            release_sock(sk);
            return res;
        }

        if ((flags & MSG_DONTWAIT) && !skb_peek(&sk->sk_receive_queue)) {
            release_sock(sk);
            return -EAGAIN;
        }

        skb = skb_dequeue(&sk->sk_receive_queue);
        if (skb) {
            struct sockaddr *addr = NULL;
            socklen_t addr_len = 0;
            int copy_len = min(skb->len, (int)buf_len);

            m->msg_name = addr;
            m->msg_namelen = addr_len;

            res = memcpy_from_msg(m, skb->data, copy_len);
            if (res < 0) {
                skb_queue_head(&sk->sk_receive_queue, skb);
                release_sock(sk);
                return res;
            }

            copied = res;
            if (copy_len < skb->len) {
                sk->sk_state = TCP_MORE;
            }

            kfree_skb(skb);
            res = copied;
            break;
        }

        if (signal_pending(current)) {
            release_sock(sk);
            return -EINTR;
        }

        sk->sk_state = TCP_WAIT;
        release_sock(sk);
        schedule();
        lock_sock(sk);
    }

    release_sock(sk);
    return res;
}

int receive_socket_message(struct kiocb *iocb, struct socket *sock, struct msghdr *m, size_t buf_len, int flags)
{
    int ret = 0;
    struct sock *sk = sock->sk;
    struct sk_buff *skb;

    lock_sock(sk);

    if (!sock->file || !sock->file->f_op) {
        ret = -EINVAL;
        goto out;
    }

    if (sock_flag(sk, SOCK_DEAD)) {
        ret = -ENOTCONN;
        goto out;
    }

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        ret = -EAGAIN;
        goto out;
    }

    if (skb->len == 0) {
        ret = -EFAULT;
        goto out;
    }

    m->msg_namelen = sk->sk_peer_name.len;
    if (m->msg_name && sk->sk_peer_name.len > 0) {
        memcpy(m->msg_name, &sk->sk_peer_name.addr, sk->sk_peer_name.len);
    }

    if (skb->data_len > buf_len) {
        ret = -EMSGSIZE;
        goto out;
    }

    ret = skb_copy_datagram_iovec(skb, 0, m->msg_iov, skb->data_len);
    if (ret < 0) {
        goto out;
    }

    ret = skb->data_len;

    skb_consume_datagram(skb);

out:
    release_sock(sk);
    return ret;
}
